    crate::hir::resolve(&checked).unwrap()
}
fn seed(count: usize, work: &mut SkeletonWork<'_, '_>) -> Vec<ExprSkeletonPath> {
    let mut paths = Vec::new();
    for n in 0..count {
        let mut path = empty_expr_path();
        path.failed = n % 3 == 0;
        path.residual = n % 3 == 1;
        work.push_expr_path(&mut paths, path, "path array input")
            .unwrap();
    }
    paths
}
